import ee, math, sys
ee.Initialize(project='earthsense-436113')

def get_brazil_geom():
    fc = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    fc1 = fc.filter(ee.Filter.eq('country_na', 'Brazil'))
    geom = ee.Algorithms.If(fc1.size().gt(0), ee.Feature(fc1.first()).geometry(), None)
    if geom is None:
        fc2 = fc.filter(ee.Filter.eq('COUNTRY_NA', 'Brazil'))
        if fc2.size().getInfo() == 0:
            return None
        return ee.Feature(fc2.first()).geometry()
    return geom

def get_ic(collection_id, year, geom):
    return (ee.ImageCollection(collection_id)
            .filterDate(f"{year}-01-01", f"{year+1}-01-01")
            .filterBounds(geom)
            .select('FireMask'))

def year_fire_counts(year, geom):
    # Try primary 061; fallback to 006 if needed
    ic_t = get_ic('MODIS/061/MOD14A1', year, geom)
    ic_a = get_ic('MODIS/061/MYD14A1', year, geom)
    size_t = ic_t.size().getInfo()
    size_a = ic_a.size().getInfo()
    if size_t == 0:
        ic_t = get_ic('MODIS/006/MOD14A1', year, geom)
        size_t = ic_t.size().getInfo()
    if size_a == 0:
        ic_a = get_ic('MODIS/006/MYD14A1', year, geom)
        size_a = ic_a.size().getInfo()
    if (size_t + size_a) == 0:
        return {'status':'C1'}

    # Valid pixel check using first available image
    first_any = ee.Image(ee.ImageCollection(ic_t.merge(ic_a)).first())
    valid_pix = first_any.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom,
        scale=1000,
        maxPixels=1e9
    ).get('FireMask')
    valid_pix = valid_pix.getInfo()
    if (valid_pix is None) or (int(valid_pix) == 0):
        return {'status':'C2'}

    def ic_sum(ic):
        # Fire detection mask: FireMask >= 7
        det_ic = ic.map(lambda img: img.gte(7).rename('det').unmask(0).toUint16())
        yearly = det_ic.sum().rename('det')
        total = yearly.reduceRegion(
            reducer=ee.Reducer.sum(),
            geometry=geom,
            scale=1000,
            maxPixels=1e9
        ).get('det')
        return total

    tot_t = ic_sum(ic_t).getInfo()
    tot_a = ic_sum(ic_a).getInfo()

    # Validation for calculation failure
    def bad(x):
        return (x is None) or (isinstance(x, float) and (math.isnan(x) or math.isinf(x))) or (x < 0)
    if bad(tot_t) or bad(tot_a):
        return {'status':'C3'}

    total = int(tot_t) + int(tot_a)
    return {
        'status':'OK',
        'images_terra': size_t,
        'images_aqua': size_a,
        'det_terra': int(tot_t),
        'det_aqua': int(tot_a),
        'det_total': int(total)
    }

def main():
    try:
        geom = get_brazil_geom()
        if geom is None:
            print("Country geometry lookup failed.")
            print("D")
            return

        res2007 = year_fire_counts(2007, geom)
        res2019 = year_fire_counts(2019, geom)

        if res2007.get('status') != 'OK' or res2019.get('status') != 'OK':
            # Propagate the first non-OK status (prefer more specific failure)
            for res in [res2007, res2019]:
                if res.get('status') != 'OK':
                    print(f"2007 Status: {res2007.get('status')}, 2019 Status: {res2019.get('status')}")
                    print(res.get('status'))
                    return

        print(f"2007 Images - Terra: {res2007['images_terra']}, Aqua: {res2007['images_aqua']}")
        print(f"2007 Detections - Terra: {res2007['det_terra']}, Aqua: {res2007['det_aqua']}, Total: {res2007['det_total']}")
        print(f"2019 Images - Terra: {res2019['images_terra']}, Aqua: {res2019['images_aqua']}")
        print(f"2019 Detections - Terra: {res2019['det_terra']}, Aqua: {res2019['det_aqua']}, Total: {res2019['det_total']}")
        fewer_2019 = res2019['det_total'] < res2007['det_total']

        print("A" if fewer_2019 else "B")
    except Exception as e:
        print(f"Error: {str(e)[:120]}")
        print("D")

if __name__ == "__main__":
    main()
